<template>
  <section class="blog-detail"><PageState v-if="state !== 'ready'" :state="state" :message="errorMessage" @retry="load"/><template v-else-if="blog"><section class="blog-gallery" aria-label="博客图片"><img v-if="images.length" :src="images[activeImage]" :alt="`${blog.title || '博客'}图片 ${activeImage + 1}`" width="720" height="540" loading="lazy"><span v-else class="blog-gallery__empty">这篇记录没有图片</span><template v-if="images.length > 1"><button type="button" class="gallery-control gallery-control--prev" aria-label="查看上一张图片" :disabled="activeImage === 0" @click="previousImage"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m14 6-6 6 6 6" fill="none" stroke="currentColor" stroke-width="2"/></svg></button><button type="button" class="gallery-control gallery-control--next" aria-label="查看下一张图片" :disabled="activeImage === images.length - 1" @click="nextImage"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m10 6 6 6-6 6" fill="none" stroke="currentColor" stroke-width="2"/></svg></button><div class="gallery-position" aria-live="polite">{{ activeImage + 1 }} / {{ images.length }}</div><div class="gallery-dots" role="tablist" aria-label="选择博客图片"><button v-for="(_, index) in images" :key="index" type="button" role="tab" :aria-selected="activeImage === index" :aria-label="`查看第 ${index + 1} 张图片`" @click="activeImage = index"></button></div></template></section><article class="blog-content"><header class="blog-author"><button type="button" class="author-profile" @click="openAuthor"><img v-if="blog.icon" :src="blog.icon" alt="" width="48" height="48" loading="lazy"><span v-else class="author-avatar" aria-hidden="true">{{ (blog.name || '探').slice(0, 1) }}</span><span><strong>{{ blog.name || '匿名探索者' }}</strong><small>{{ blog.createTime || '刚刚发布' }}</small></span></button><button v-if="canToggleFollow" type="button" class="follow-button" :disabled="following" @click="toggleFollow">{{ following ? '处理中…' : followed ? '已关注' : '关注' }}</button></header><h1>{{ blog.title || '未命名探店记录' }}</h1><p data-test="blog-body" class="blog-body">{{ blog.content || '' }}</p></article><button v-if="shop" type="button" class="related-shop" @click="openShop"><span><strong>{{ shop.name || '关联门店' }}</strong><small>{{ shop.area || shop.address || '查看门店详情' }}</small></span><svg viewBox="0 0 24 24" aria-hidden="true"><path d="m9 6 6 6-6 6" fill="none" stroke="currentColor" stroke-width="2"/></svg></button><section class="blog-actions"><button type="button" data-test="blog-like" :aria-pressed="!!blog.isLike" :disabled="liking" @click="toggleLike"><svg viewBox="0 0 24 24" aria-hidden="true"><path d="M12 20 4 12.4A5 5 0 0 1 11 5.2L12 6.3l1.1-1.1a5 5 0 0 1 7 7.2L12 20Z" fill="none" stroke="currentColor" stroke-width="1.8"/></svg>{{ liking ? '处理中…' : `${blog.liked || 0} 人点赞` }}</button><div v-if="likes.length" class="like-users" aria-label="点赞用户"><img v-for="user in likes" :key="user.id" :src="user.icon" :alt="user.nickName || '点赞用户'" width="28" height="28" loading="lazy"></div></section></template></section>
</template>

<script setup lang="ts">
import { computed, ref, watch } from 'vue'
import { ElMessage } from 'element-plus'
import { useRoute, useRouter } from 'vue-router'
import { getBlog, getBlogLikes, likeBlog } from '@/api/blog'
import { getShop } from '@/api/shop'
import { getFollowStatus, setFollow } from '@/api/follow'
import { getCurrentUser } from '@/api/user'
import { useAuthStore } from '@/stores/auth'
import PageState from '@/components/common/PageState.vue'
import type { Blog, Shop, User } from '@/types/api'
type ViewState = 'loading' | 'error' | 'empty' | 'ready'
const route = useRoute(); const router = useRouter(); const auth = useAuthStore(); const blog = ref<Blog>(); const shop = ref<Shop>(); const likes = ref<User[]>([]); const currentUser = ref<User | null>(auth.user); const identityState = ref<'known' | 'pending' | 'unknown'>(auth.isAuthenticated && !auth.user ? 'pending' : 'known'); const state = ref<ViewState>('loading'); const errorMessage = ref(''); const activeImage = ref(0); const followed = ref(false); const liking = ref(false); const following = ref(false); let pageEpoch = 0
const blogId = computed(() => Number(route.params.id)); const images = computed(() => blog.value?.images?.split(',').map((item) => item.trim()).filter(Boolean) || []); const isOwnBlog = computed(() => currentUser.value?.id !== undefined && currentUser.value.id === blog.value?.userId); const canToggleFollow = computed(() => !isOwnBlog.value && (!auth.isAuthenticated || identityState.value === 'known'))
function redirectToLogin() { return router.push({ name: 'login', query: { redirect: route.fullPath } }) }
function isCurrentPage(epoch: number, targetBlogId: number) { return pageEpoch === epoch && blogId.value === targetBlogId }
function resetPage() { blog.value = undefined; shop.value = undefined; likes.value = []; currentUser.value = auth.user; identityState.value = auth.isAuthenticated && !auth.user ? 'pending' : 'known'; activeImage.value = 0; followed.value = false; liking.value = false; following.value = false; errorMessage.value = '' }
async function loadLikes(id: number, epoch: number, targetBlogId: number) { try { const next = await getBlogLikes(id); if (isCurrentPage(epoch, targetBlogId)) likes.value = next } catch { if (isCurrentPage(epoch, targetBlogId)) likes.value = [] } }
async function loadAuxiliary(loaded: Blog, epoch: number, targetBlogId: number) { if (loaded.shopId !== undefined) { try { const nextShop = await getShop(loaded.shopId); if (isCurrentPage(epoch, targetBlogId)) shop.value = nextShop } catch { if (isCurrentPage(epoch, targetBlogId)) shop.value = undefined } } if (typeof loaded.id === 'number' && Number.isInteger(loaded.id) && loaded.id > 0) await loadLikes(loaded.id, epoch, targetBlogId); if (!auth.isAuthenticated || !isCurrentPage(epoch, targetBlogId)) return; if (!currentUser.value) { identityState.value = 'pending'; try { const current = await getCurrentUser(); if (!isCurrentPage(epoch, targetBlogId)) return; currentUser.value = current; identityState.value = 'known' } catch { if (!isCurrentPage(epoch, targetBlogId)) return; identityState.value = 'unknown'; return } } if (currentUser.value?.id !== loaded.userId && loaded.userId !== undefined) { try { const status = await getFollowStatus(loaded.userId); if (isCurrentPage(epoch, targetBlogId) && blog.value?.userId === loaded.userId) followed.value = status } catch { if (isCurrentPage(epoch, targetBlogId) && blog.value?.userId === loaded.userId) followed.value = false } } }
async function load() { const epoch = ++pageEpoch; const targetBlogId = blogId.value; resetPage(); if (!Number.isInteger(targetBlogId) || targetBlogId < 1) { state.value = 'error'; errorMessage.value = '博客地址无效，请返回后重新选择。'; return } state.value = 'loading'; try { const loaded = await getBlog(targetBlogId); if (!isCurrentPage(epoch, targetBlogId)) return; if (!loaded) { state.value = 'error'; errorMessage.value = '博客不存在或已删除，请稍后重试。'; return } blog.value = loaded; await loadAuxiliary(loaded, epoch, targetBlogId); if (isCurrentPage(epoch, targetBlogId)) state.value = 'ready' } catch { if (!isCurrentPage(epoch, targetBlogId)) return; state.value = 'error'; errorMessage.value = '博客详情加载失败，请稍后重试。' } }
function previousImage() { activeImage.value = Math.max(0, activeImage.value - 1) } function nextImage() { activeImage.value = Math.min(images.value.length - 1, activeImage.value + 1) }
function openAuthor() { if (blog.value?.userId === undefined) return; void router.push(isOwnBlog.value ? { name: 'me' } : { name: 'user-profile', params: { id: blog.value.userId } }) } function openShop() { if (shop.value?.id !== undefined) void router.push({ name: 'shop-detail', params: { id: shop.value.id } }) }
async function toggleLike() { if (!auth.isAuthenticated) { await redirectToLogin(); return } const id = blog.value?.id; const authorId = blog.value?.userId; const routeTargetId = blogId.value; const epoch = pageEpoch; if (id === undefined || liking.value) return; const isCurrentAction = () => isCurrentPage(epoch, routeTargetId) && blog.value?.id === id && blog.value?.userId === authorId; liking.value = true; try { await likeBlog(id); if (!isCurrentAction()) return; const refreshed = await getBlog(id); if (!isCurrentAction()) return; if (refreshed) blog.value = refreshed; await loadLikes(id, epoch, routeTargetId) } catch { if (!isCurrentAction()) return; ElMessage.error('点赞未成功，请稍后重试') } finally { if (isCurrentAction()) liking.value = false } }
async function toggleFollow() { if (!auth.isAuthenticated) { await redirectToLogin(); return } const authorId = blog.value?.userId; const targetBlogId = blog.value?.id; const routeTargetId = blogId.value; const epoch = pageEpoch; if (identityState.value !== 'known' || authorId === undefined || targetBlogId === undefined || following.value) return; const isCurrentAction = () => isCurrentPage(epoch, routeTargetId) && blog.value?.id === targetBlogId && blog.value?.userId === authorId; following.value = true; try { await setFollow(authorId, !followed.value); if (!isCurrentAction()) return; followed.value = !followed.value; ElMessage.success(followed.value ? '已关注' : '已取消关注') } catch { if (!isCurrentAction()) return; ElMessage.error('关注操作未成功，请稍后重试') } finally { if (isCurrentAction()) following.value = false } }
void load(); watch(() => route.params.id, () => { void load() })
</script>

<style scoped>
.blog-detail{max-width:860px;margin:0 auto}.blog-gallery{position:relative;display:grid;place-items:center;min-height:260px;overflow:hidden;border-radius:var(--radius-card);background:#fde9dc}.blog-gallery>img{width:100%;aspect-ratio:4/3;object-fit:cover}.blog-gallery__empty{color:var(--color-primary)}.gallery-control{position:absolute;top:calc(50% - 22px);display:grid;place-items:center;width:44px;height:44px;padding:0;border:0;border-radius:50%;background:rgba(44,35,32,.72);color:#fff;cursor:pointer}.gallery-control:disabled{opacity:.35;cursor:not-allowed}.gallery-control svg,.related-shop svg,.blog-actions svg{width:22px}.gallery-control--prev{left:12px}.gallery-control--next{right:12px}.gallery-position{position:absolute;right:12px;bottom:12px;padding:3px 8px;border-radius:999px;background:rgba(44,35,32,.72);color:#fff;font-size:.78rem}.gallery-dots{position:absolute;bottom:12px;left:12px;display:flex;gap:6px}.gallery-dots button{width:10px;height:10px;padding:0;border:1px solid #fff;border-radius:50%;background:transparent;cursor:pointer}.gallery-dots button[aria-selected="true"]{background:#fff}.blog-content,.related-shop,.blog-actions{margin-top:16px;border:1px solid var(--color-border);border-radius:var(--radius-card);background:var(--color-surface);box-shadow:var(--shadow-card)}.blog-content{padding:18px}.blog-author{display:flex;align-items:center;justify-content:space-between;gap:12px}.author-profile{display:flex;align-items:center;gap:10px;min-width:0;padding:0;border:0;background:transparent;color:inherit;font:inherit;text-align:left;cursor:pointer}.author-profile img,.author-avatar{width:48px;height:48px;flex:none;border-radius:50%;object-fit:cover}.author-avatar{display:grid;place-items:center;background:#f7c8af;color:#884625;font-weight:700}.author-profile span:last-child{display:grid;gap:2px}.author-profile small{color:var(--color-muted);font-size:.78rem}.follow-button,.blog-actions>button{min-height:44px;padding:8px 14px;border:1px solid var(--color-primary);border-radius:var(--radius-control);background:#fff0ea;color:var(--color-primary);font:inherit;font-weight:700;cursor:pointer}.follow-button:disabled,.blog-actions>button:disabled{cursor:wait;opacity:.6}.blog-content h1{margin:18px 0 10px;font-size:clamp(1.45rem,3vw,2rem)}.blog-body{margin:0;white-space:pre-wrap;overflow-wrap:anywhere}.related-shop{display:flex;align-items:center;justify-content:space-between;width:100%;min-height:72px;padding:14px 18px;color:inherit;font:inherit;text-align:left;cursor:pointer}.related-shop span{display:grid;gap:4px}.related-shop small{color:var(--color-muted)}.blog-actions{display:flex;align-items:center;gap:12px;padding:10px}.blog-actions>button{display:inline-flex;align-items:center;gap:6px;border-color:transparent;background:transparent}.blog-actions>button[aria-pressed="true"]{background:#fff0ea}.like-users{display:flex;overflow:hidden}.like-users img{width:28px;height:28px;margin-left:-6px;border:2px solid #fff;border-radius:50%;object-fit:cover}.like-users img:first-child{margin-left:0}
</style>
